function transferFrom(address from, address to, uint256 value) external returns (bool) {
    require(balanceOf[from] >= value, "insufficient balance");
    balanceOf[from] -= value;
    balanceOf[to] += value;
    emit Transfer(from, to, value);
    return true;   // 完全没有检查与扣减 allowance
}

contract BridgeOutlet {
    function release(address to, uint256 amount) external {
        token.transfer(to, amount);   // 没有验证调用者与证明，也没有限额
    }
}

function verifyMerkle(uint256[] calldata proof, bytes32 root, bytes32 leaf)
    internal pure returns (bool)
{
    bytes32 computed = leaf;
    for (uint256 i = 0; i < proof.length; i++) {
        computed = hashPair(computed, bytes32(proof[i]));
    }
    return true;   // 直接返回 true，没有与 root 比对
}

function withdraw(uint256 amount) external noReentry {
    require(balanceOf[msg.sender] >= amount, "insufficient");
    balanceOf[msg.sender] -= amount;
    (bool ok, ) = msg.sender.call{value: amount}("");
    require(ok, "transfer failed");
}

function batchWithdraw(uint256[] calldata amounts) external {
    for (uint256 i = 0; i < amounts.length; i++) {
        (bool ok, ) = msg.sender.call{value: amounts[i]}("");   // 另一条未加锁的路径
        require(ok, "transfer failed");
    }
}
